"""REST endpoints (all mounted under /api)."""

from __future__ import annotations

import importlib
import math
from typing import Any, Callable

import numpy as np
from fastapi import APIRouter, HTTPException

from ..models.requests import (
    AnticrossingRequest,
    DispersionRequest,
    DMatrixRequest,
    FieldsRequest,
    OpticsRequest,
    ThicknessMapRequest,
)
from ..models.stack import material_to_json, parse_stack, stack_to_json
from ..physics.anticrossing import analyze_anticrossings, thickness_map
from ..physics.d_matrix import build_d_es, build_k_system, solve_es_dispersion, solve_es_modes
from ..physics.d_matrix_retarded import build_d_ret_regularized
from ..physics.fields import compute_fields
from ..physics.materials import get_default_materials
from ..physics.presets import HeterostructureSpec, get_presets

router = APIRouter(prefix="/api")


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------


def clean_json(obj: Any) -> Any:
    """Recursively convert numpy types to Python and non-finite floats to None."""
    if isinstance(obj, dict):
        return {str(k): clean_json(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [clean_json(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return clean_json(obj.tolist())
    if isinstance(obj, (bool, np.bool_)):
        return bool(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (float, np.floating)):
        f = float(obj)
        return f if math.isfinite(f) else None
    if isinstance(obj, complex):
        return {"re": clean_json(obj.real), "im": clean_json(obj.imag)}
    return obj


def _stack(raw: dict[str, Any]) -> HeterostructureSpec:
    return parse_stack(raw)


def _optional_solver(module: str, name: str) -> Callable[..., dict[str, Any]]:
    """Lazy import of the retarded / optics solvers (developed in parallel)."""
    try:
        mod = importlib.import_module(f"..physics.{module}", package=__package__)
        return getattr(mod, name)
    except (ImportError, AttributeError) as exc:
        raise HTTPException(status_code=501, detail=f"app.physics.{module}.{name} is not available: {exc}") from exc


def _req_dict(req: Any) -> dict[str, Any]:
    return req.model_dump()


def _finite_matrix(m: np.ndarray, what: str) -> None:
    if not np.all(np.isfinite(m)):
        raise ValueError(f"{what} is not finite at the requested (w, q) (pole of a permittivity).")


# ---------------------------------------------------------------------------
# catalogue
# ---------------------------------------------------------------------------


@router.get("/health")
def health() -> dict[str, Any]:
    return {"status": "ok", "service": "simulador_heteroestructuras", "api_version": "1.0"}


@router.get("/presets")
def presets() -> dict[str, Any]:
    out = []
    for p in get_presets():
        out.append(
            {
                "id": p.id,
                "tfg_id": p.tfg_id,
                "memory_name": p.memory_name,
                "category": p.category,
                "description": p.description,
                "stack": stack_to_json(p.stack),
            }
        )
    return clean_json({"presets": out})


@router.get("/materials")
def materials() -> dict[str, Any]:
    return clean_json({"materials": [material_to_json(m) for m in get_default_materials().values()]})


# ---------------------------------------------------------------------------
# simulations
# ---------------------------------------------------------------------------


@router.post("/simulate/d-matrix")
def simulate_d_matrix(req: DMatrixRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    n = len(stack.layers) - 1
    if n < 1:
        raise ValueError("The interface D-matrix needs at least one interface (bulk P1 has N = 0).")
    q, w = float(req.q_ev), float(req.w_ev)
    try:
        if req.retarded:
            d_mat, scales = build_d_ret_regularized(stack, w, q, loss_scale=req.loss_scale)
        else:
            d_mat = build_d_es(stack, w, q, loss_scale=req.loss_scale)
            scales = None
    except ZeroDivisionError as exc:
        raise ValueError(f"w_ev = {w} coincides with a pole of a permittivity.") from exc
    _finite_matrix(d_mat, "D")
    # det D via slogdet: for many layers |det D| over/underflows float64 although D itself is finite.
    sign, logabs = np.linalg.slogdet(d_mat)
    sign = complex(sign)
    logabs = float(logabs)
    if math.isnan(logabs) or not (math.isfinite(sign.real) and math.isfinite(sign.imag)):
        raise ValueError("det D is not finite at the requested (w, q).")
    if logabs == -math.inf:
        det: complex | None = 0j
    elif logabs < 709.0:
        det = sign * math.exp(logabs)
    else:
        det = None  # |det D| > 1e308: reported through det_log10_abs / det_phase only
    det_log10_abs = logabs / math.log(10.0) if math.isfinite(logabs) else None

    es = solve_es_modes(stack, q)
    k_mat = es.k_matrix
    if k_mat is None:
        try:
            _, k_mat, _, _ = build_k_system(stack, q)
        except ValueError:
            k_mat = None
    out: dict[str, Any] = {
        "n_interfaces": n,
        "q_ev": q,
        "w_ev": w,
        "kx_nm_inv": q / 197.3269804,
        "retarded": bool(req.retarded),
        "regularized": bool(req.retarded),
        "row_scales_real": None if scales is None else np.real(scales).tolist(),
        "row_scales_imag": None if scales is None else np.imag(scales).tolist(),
        "d_matrix_real": np.real(d_mat).tolist(),
        "d_matrix_imag": np.imag(d_mat).tolist(),
        "det_real": None if det is None else det.real,
        "det_imag": None if det is None else det.imag,
        "det_log10_abs": det_log10_abs,
        "det_phase": math.atan2(sign.imag, sign.real),
        "es_roots_ev": [float(r) for r in es.roots_ev],
        "generic_degree": int(es.generic_degree),
        "reduced_degree": int(es.reduced_degree),
        "spurious_removed": [[float(wt), int(mult)] for wt, mult in es.spurious_removed],
        "k_matrix": None if k_mat is None or k_mat.size == 0 else np.asarray(k_mat).tolist(),
        "lo_modes_ev": None if es.lo_modes_ev is None else [float(x) for x in es.lo_modes_ev],
        "has_hyperbolic": bool(es.has_hyperbolic),
    }
    return clean_json(out)


@router.post("/simulate/dispersion")
def simulate_dispersion(req: DispersionRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    if req.q_spacing == "log":
        q_grid = np.exp(np.linspace(math.log(req.q_min_ev), math.log(req.q_max_ev), req.n_q))
    else:
        q_grid = np.linspace(req.q_min_ev, req.q_max_ev, req.n_q)
    res = solve_es_dispersion(stack, q_grid, include_bare=req.include_bare)
    coupled = np.asarray(res.coupled_branches_ev, dtype=float)
    finite_cols = np.isfinite(coupled)
    counts = finite_cols.sum(axis=0) if coupled.size else np.zeros(len(q_grid), dtype=int)
    all_roots = [coupled[: int(counts[k]), k].tolist() for k in range(len(q_grid))]
    truncated = bool(coupled.size and counts.min() != counts.max())
    if truncated:
        # Hyperbolic (uniaxial) slabs support an unbounded, q-dependent set of volume modes: the
        # rectangular array keeps the n_min lowest roots at every q (band-index ordering); the
        # complete root list per q is returned in all_roots_ev.
        coupled = coupled[: int(counts.min()), :]
    out: dict[str, Any] = {
        "q_ev": res.q_ev.tolist(),
        "kx_nm_inv": res.kx_nm_inv.tolist(),
        "coupled_branches_ev": coupled.tolist(),
        "all_roots_ev": all_roots,
        "n_roots_per_q": counts.tolist(),
        "branches_truncated": truncated,
        "bare_plasmons_ev": [] if res.bare_plasmons_ev is None else res.bare_plasmons_ev.tolist(),
        "bare_phonons_ev": [] if res.bare_phonons_ev is None else res.bare_phonons_ev.tolist(),
        "char_freqs": res.char_freqs,
        "spurious_removed": [[float(wt), int(mult)] for wt, mult in res.spurious_removed],
        "include_retarded": bool(req.include_retarded),
        "loss_scale": req.loss_scale,
    }
    if req.include_retarded:
        fn = _optional_solver("retarded", "compute_retarded_dispersion")
        extra = fn(stack, _req_dict(req))
        if isinstance(extra, dict):
            out.update(extra)
    return clean_json(out)


@router.post("/simulate/anticrossing")
def simulate_anticrossing(req: AnticrossingRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    res = analyze_anticrossings(stack, req.q_min_ev, req.q_max_ev, req.n_q, req.tau_ps)
    return clean_json(res)


@router.post("/simulate/thickness-map")
def simulate_thickness_map(req: ThicknessMapRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    res = thickness_map(
        stack,
        req.d_grid_nm,
        req.h_grid_nm,
        q_min_ev=req.q_min_ev,
        q_max_ev=req.q_max_ev,
        n_q=req.n_q,
        tau_ps=req.tau_ps,
    )
    return clean_json(res)


@router.post("/simulate/fields")
def simulate_fields(req: FieldsRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    res = compute_fields(stack, req.q_ev, req.w_ev, req.branch_index, req.n_z)
    return clean_json(res)


@router.post("/simulate/optics")
def simulate_optics(req: OpticsRequest) -> dict[str, Any]:
    stack = _stack(req.stack)
    fn = _optional_solver("optics", "compute_optics")
    return clean_json(fn(stack, _req_dict(req)))

