"""Pydantic request models for the simulation endpoints.

The ``stack`` field is kept as a raw JSON object and parsed by :func:`app.models.stack.parse_stack`
(see that module for the full stack schema).  Unknown extra fields are accepted (``extra="allow"``)
so the raw body can be forwarded unchanged to the retarded / optics solvers.
"""

from __future__ import annotations

from typing import Any, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, StrictBool, model_validator


THICKNESS_MAP_MAX_POINTS = 200_000  # (d, h, q) evaluations allowed in one thickness-map request


class _Base(BaseModel):
    model_config = ConfigDict(extra="allow")

    stack: dict[str, Any] = Field(..., description="Heterostructure stack (see app.models.stack).")


class DMatrixRequest(_Base):
    q_ev: float = Field(..., gt=0.0, description="q = hbar c k_x (eV)")
    w_ev: float = Field(..., gt=0.0, description="hbar omega (eV) at which D is evaluated")
    retarded: StrictBool = False
    loss_scale: float = Field(0.0, ge=0.0, description="Multiplier of all material / graphene losses")


class DispersionRequest(_Base):
    q_min_ev: float = Field(..., gt=0.0)
    q_max_ev: float = Field(..., gt=0.0)
    n_q: int = Field(..., ge=2, le=2000)
    include_bare: StrictBool = True
    include_retarded: StrictBool = False
    loss_scale: float = Field(0.0, ge=0.0)
    q_spacing: Literal["linear", "log"] = "linear"

    @model_validator(mode="after")
    def _check_range(self) -> "DispersionRequest":
        if not self.q_max_ev > self.q_min_ev:
            raise ValueError("q_max_ev must be > q_min_ev")
        return self


class AnticrossingRequest(_Base):
    q_min_ev: float = Field(0.01, gt=0.0)
    q_max_ev: float = Field(3000.0, gt=0.0)
    n_q: int = Field(801, ge=3, le=5000)
    tau_ps: float = Field(0.1, gt=0.0, description="Graphene relaxation time used for the loss criterion")

    @model_validator(mode="after")
    def _check_range(self) -> "AnticrossingRequest":
        if not self.q_max_ev > self.q_min_ev:
            raise ValueError("q_max_ev must be > q_min_ev")
        return self


class ThicknessMapRequest(_Base):
    d_grid_nm: list[float] = Field(..., min_length=1, max_length=200)
    h_grid_nm: Optional[list[float]] = Field(None, max_length=200)
    tau_ps: float = Field(0.1, gt=0.0)
    q_min_ev: float = Field(0.01, gt=0.0)
    q_max_ev: float = Field(3000.0, gt=0.0)
    n_q: int = Field(801, ge=3, le=5000)

    @model_validator(mode="after")
    def _check(self) -> "ThicknessMapRequest":
        for x in self.d_grid_nm + (self.h_grid_nm or []):
            if not (x > 0.0 and x < float("inf")):
                raise ValueError("thickness grid values must be finite and > 0")
        if self.h_grid_nm is not None and len(self.h_grid_nm) == 0:
            raise ValueError("h_grid_nm must be null or non-empty")
        if not self.q_max_ev > self.q_min_ev:
            raise ValueError("q_max_ev must be > q_min_ev")
        n_h = len(self.h_grid_nm) if self.h_grid_nm else 1
        cost = len(self.d_grid_nm) * n_h * self.n_q
        if cost > THICKNESS_MAP_MAX_POINTS:
            raise ValueError(
                f"thickness map too large: len(d_grid_nm) * len(h_grid_nm or [1]) * n_q = {cost} > "
                f"{THICKNESS_MAP_MAX_POINTS}; reduce the grids or n_q."
            )
        return self


class FieldsRequest(_Base):
    q_ev: float = Field(..., gt=0.0)
    w_ev: Optional[float] = Field(None, gt=0.0, description="Explicit energy; null -> use branch_index")
    branch_index: int = Field(0, ge=0)
    n_z: int = Field(401, ge=2, le=20001)


class OpticsRequest(_Base):
    """Generic sanity checks here; the optics solver receives the raw body and validates the rest."""

    mode: Literal["planar", "planar_map", "grating", "grating_map"] = "planar"
    w_min_ev: float = Field(..., gt=0.0)
    w_max_ev: float = Field(..., gt=0.0)
    n_w: int = Field(..., ge=1, le=20000)
    theta_deg: float = Field(0.0, ge=0.0, lt=90.0)
    polarization: Literal["TM", "TE"] = "TM"
    loss_scale: float = Field(1.0, ge=0.0)
    period_nm: Optional[float] = Field(None, gt=0.0)
    slit_width_nm: Optional[float] = Field(None, gt=0.0)
    metal_thickness_nm: Optional[float] = Field(None, gt=0.0)
    n_max: Optional[int] = Field(None, ge=0)
    period_grid_nm: Optional[list[float]] = None

    @model_validator(mode="after")
    def _check(self) -> "OpticsRequest":
        if not self.w_max_ev > self.w_min_ev:
            raise ValueError("w_max_ev must be > w_min_ev")
        if self.mode in ("grating", "grating_map"):
            if self.period_nm is None and not self.period_grid_nm:
                raise ValueError("grating modes need period_nm (or period_grid_nm)")
            if self.slit_width_nm is not None and self.period_nm is not None and not self.slit_width_nm < self.period_nm:
                raise ValueError("slit_width_nm must be < period_nm")
            if self.mode == "grating_map":
                if not self.period_grid_nm:
                    raise ValueError("grating_map needs a non-empty period_grid_nm")
                if any(not (p > 0.0) for p in self.period_grid_nm):
                    raise ValueError("period_grid_nm values must be > 0")
        return self

