"""JSON stack <-> HeterostructureSpec conversion with strict validation.

Request schema (all energies in eV, thicknesses in nm, layers listed top -> bottom)::

    stack = {
      "layers": [
        {"material": MATERIAL, "thickness_nm": null | float, "graphene_top": GRAPHENE | null},
        ...
      ],
      "interfaces": [GRAPHENE, ...]          # optional, len == len(layers) - 1; overrides graphene_top
      "pec_bottom": false                     # true -> perfect conductor below the last (finite) layer
    }

    MATERIAL = "sio2"                         # catalog id (string), or
             | {"id": "sio2"}                 # catalog reference (no "kind"), or one of
             | {"kind": "dielectric", "eps_inf"}
             | {"kind": "lorentz", "eps_inf", "w_t", "w_l", "gamma"=0}
             | {"kind": "drude", "eps_inf"=1, "w_p", "gamma"=0}
             | {"kind": "multi_lorentz", "eps_inf", "oscillators": [{"w_t", "w_l"|"strength", "gamma"=0}],
                "form": "additive"|"lst", "w_p"=0, "gamma"=0}
             | {"kind": "uniaxial_hbn"|"uniaxial", "parallel": AXIS, "perp": AXIS}
                  AXIS = {"eps_inf", "w_t", "w_l", "gamma"=0}  (in-plane / out-of-plane)
             | {"kind": "pec"}                # only as the last layer: equivalent to pec_bottom=true

    GRAPHENE = {"enabled": true, "ef_ev": 0.63, "tau_ps": null | float, "gamma_ev": null | float,
                "model": "drude" | "kubo", "temperature_k": 300, "scale": 1}

``graphene_top`` of layer i (i >= 1) is the sheet on the interface between layer i-1 and layer i.
Semi-infinite media have ``thickness_nm = null``; the top medium is always semi-infinite, the bottom
one too unless ``pec_bottom`` is true (then it must be a finite spacer: graphene directly on a PEC is
rejected).
"""

from __future__ import annotations

import copy
import math
from dataclasses import asdict
from typing import Any

from ..physics.materials import (
    GrapheneSpec,
    LorentzOscillator,
    MaterialSpec,
    UniaxialAxisParams,
    get_default_materials,
)
from ..physics.presets import HeterostructureSpec, LayerSpec, validate_stack


class StackError(ValueError):
    """Invalid stack / material / graphene specification (mapped to HTTP 422)."""


_KIND_ALIASES = {
    "dielectric": "dielectric",
    "constant": "dielectric",
    "lorentz": "lorentz",
    "polar": "lorentz",
    "drude": "drude",
    "multi_lorentz": "multi_lorentz",
    "multilorentz": "multi_lorentz",
    "uniaxial_hbn": "uniaxial_hbn",
    "uniaxial": "uniaxial_hbn",
    "hbn": "uniaxial_hbn",
    "pec": "pec",
}


def _num(d: dict[str, Any], key: str, where: str, default: float | None = None, required: bool = False) -> float:
    val = d.get(key, None)
    if val is None:
        if required or default is None:
            if required:
                raise StackError(f"{where}: missing required numeric field '{key}'.")
            return default  # type: ignore[return-value]
        return float(default)
    if isinstance(val, bool) or not isinstance(val, (int, float)):
        raise StackError(f"{where}: field '{key}' must be a number (got {val!r}).")
    f = float(val)
    if not math.isfinite(f):
        raise StackError(f"{where}: field '{key}' must be finite (got {val!r}).")
    return f


MAX_LAYERS = 60  # upper bound on the number of layers of a stack (cost and det-overflow guard)


def _strict_bool(d: dict[str, Any], key: str, where: str, default: bool) -> bool:
    """JSON boolean field: only true/false (or absent/null -> default); anything else is a StackError."""
    val = d.get(key, None)
    if val is None:
        return default
    if not isinstance(val, bool):
        raise StackError(f"{where}: field '{key}' must be a JSON boolean true/false (got {val!r}).")
    return val


def _parse_axis(raw: Any, where: str) -> UniaxialAxisParams:
    if not isinstance(raw, dict):
        raise StackError(f"{where}: axis parameters must be an object.")
    oscs = None
    if raw.get("oscillators"):
        oscs = [_parse_oscillator(o, f"{where}.oscillators[{i}]") for i, o in enumerate(raw["oscillators"])]
    eps_inf = _num(raw, "eps_inf", where, required=True)
    w_t = _num(raw, "w_t", where, default=0.0, required=oscs is None)
    w_l = _num(raw, "w_l", where, default=0.0, required=oscs is None)
    gamma = _num(raw, "gamma", where, default=0.0)
    if oscs is not None and not w_t:
        # Reference (first) oscillator of the axis.  With only a 'strength' given, its effective
        # LO frequency is the zero of eps_inf + S w_T^2 / (w_T^2 - w^2): w_L = w_T sqrt(1 + S / eps_inf).
        w_t = oscs[0].w_t
        if oscs[0].w_l is not None:
            w_l = oscs[0].w_l
        elif oscs[0].strength is not None and oscs[0].strength > 0.0 and eps_inf > 0.0:
            w_l = w_t * math.sqrt(1.0 + oscs[0].strength / eps_inf)
        else:
            w_l = w_t
    return UniaxialAxisParams(eps_inf=eps_inf, w_t=w_t, w_l=w_l, gamma=gamma, oscillators=oscs)


def _parse_oscillator(raw: Any, where: str) -> LorentzOscillator:
    if not isinstance(raw, dict):
        raise StackError(f"{where}: oscillator must be an object.")
    w_t = _num(raw, "w_t", where, required=True)
    w_l = raw.get("w_l")
    strength = raw.get("strength")
    if w_l is None and strength is None:
        raise StackError(f"{where}: oscillator needs 'w_l' or 'strength'.")
    osc = LorentzOscillator(
        w_t=w_t,
        w_l=None if w_l is None else _num(raw, "w_l", where),
        strength=None if strength is None else _num(raw, "strength", where),
        gamma=_num(raw, "gamma", where, default=0.0),
    )
    if osc.w_t <= 0.0:
        raise StackError(f"{where}: oscillator requires w_t > 0.")
    if osc.w_l is not None and osc.w_l <= osc.w_t:
        raise StackError(f"{where}: oscillator requires w_l > w_t.")
    if osc.gamma < 0.0:
        raise StackError(f"{where}: oscillator requires gamma >= 0.")
    return osc


def parse_material(raw: Any, where: str = "material") -> MaterialSpec:
    """Parse a MATERIAL JSON (catalog reference or explicit definition)."""
    catalog = get_default_materials()
    if isinstance(raw, str):
        key = raw.strip().lower()
        if key not in catalog:
            raise StackError(f"{where}: unknown catalog material id {raw!r}.")
        return copy.deepcopy(catalog[key])
    if not isinstance(raw, dict):
        raise StackError(f"{where}: material must be an object or a catalog id string.")
    kind_raw = raw.get("kind")
    mid = str(raw.get("id") or raw.get("name") or "custom")
    name = str(raw.get("name") or mid)
    if kind_raw is None:
        key = str(raw.get("id", "")).strip().lower()
        if key in catalog:
            return copy.deepcopy(catalog[key])
        raise StackError(f"{where}: material needs a 'kind' (or a known catalog 'id').")
    kind = _KIND_ALIASES.get(str(kind_raw).strip().lower())
    if kind is None:
        raise StackError(
            f"{where}: unknown material kind {kind_raw!r}; expected one of "
            "dielectric, lorentz, drude, multi_lorentz, uniaxial_hbn, pec."
        )

    if kind == "pec":
        return MaterialSpec(id=mid, name=name, kind="pec")
    if kind == "dielectric":
        mat = MaterialSpec(id=mid, name=name, kind="dielectric", eps_inf=_num(raw, "eps_inf", where, required=True))
    elif kind == "lorentz":
        mat = MaterialSpec(
            id=mid,
            name=name,
            kind="lorentz",
            eps_inf=_num(raw, "eps_inf", where, required=True),
            w_t=_num(raw, "w_t", where, required=True),
            w_l=_num(raw, "w_l", where, required=True),
            gamma=_num(raw, "gamma", where, default=0.0),
        )
    elif kind == "drude":
        mat = MaterialSpec(
            id=mid,
            name=name,
            kind="drude",
            eps_inf=_num(raw, "eps_inf", where, default=1.0),
            w_p=_num(raw, "w_p", where, required=True),
            gamma=_num(raw, "gamma", where, default=0.0),
        )
    elif kind == "multi_lorentz":
        oscs_raw = raw.get("oscillators")
        if not isinstance(oscs_raw, list) or not oscs_raw:
            raise StackError(f"{where}: multi_lorentz needs a non-empty 'oscillators' list.")
        form = str(raw.get("form", raw.get("multi_form", "additive"))).lower()
        if form not in ("additive", "lst"):
            raise StackError(f"{where}: multi_lorentz 'form' must be 'additive' or 'lst'.")
        mat = MaterialSpec(
            id=mid,
            name=name,
            kind="multi_lorentz",
            eps_inf=_num(raw, "eps_inf", where, required=True),
            w_p=_num(raw, "w_p", where, default=0.0),
            gamma=_num(raw, "gamma", where, default=0.0),
            multi_form=form,  # type: ignore[arg-type]
            oscillators=[_parse_oscillator(o, f"{where}.oscillators[{i}]") for i, o in enumerate(oscs_raw)],
        )
    else:  # uniaxial
        par = _parse_axis(raw.get("parallel"), f"{where}.parallel")
        perp = _parse_axis(raw.get("perp"), f"{where}.perp")
        mat = MaterialSpec(
            id=mid, name=name, kind="uniaxial_hbn", eps_inf=par.eps_inf, parallel=par, perp=perp
        )
    return mat


def parse_graphene(raw: Any, where: str = "graphene") -> GrapheneSpec:
    """Parse a GRAPHENE JSON (None -> disabled sheet)."""
    if raw is None or raw is False:
        return GrapheneSpec(enabled=False)
    if raw is True:
        return GrapheneSpec(enabled=True)
    if not isinstance(raw, dict):
        raise StackError(f"{where}: graphene must be an object or null.")
    enabled = _strict_bool(raw, "enabled", where, default=True)
    model = str(raw.get("model", "drude")).strip().lower()
    if model not in ("drude", "kubo"):
        raise StackError(f"{where}: graphene model must be 'drude' or 'kubo' (got {raw.get('model')!r}).")
    tau = raw.get("tau_ps")
    gamma = raw.get("gamma_ev")
    g = GrapheneSpec(
        enabled=enabled,
        ef_ev=_num(raw, "ef_ev", where, default=0.63),
        tau_ps=None if tau is None else _num(raw, "tau_ps", where),
        gamma_ev=None if gamma is None else _num(raw, "gamma_ev", where),
        model=model,  # type: ignore[arg-type]
        temperature_k=_num(raw, "temperature_k", where, default=300.0),
        scale=_num(raw, "scale", where, default=1.0),
    )
    if enabled:
        if g.ef_ev <= 0.0:
            raise StackError(f"{where}: graphene requires ef_ev > 0.")
        if g.tau_ps is not None and g.tau_ps <= 0.0:
            raise StackError(f"{where}: graphene requires tau_ps > 0 (or null for the lossless limit).")
        if g.gamma_ev is not None and g.gamma_ev < 0.0:
            raise StackError(f"{where}: graphene requires gamma_ev >= 0.")
        if g.temperature_k <= 0.0:
            raise StackError(f"{where}: graphene requires temperature_k > 0.")
        if g.scale < 0.0:
            raise StackError(f"{where}: graphene requires scale >= 0.")
    return g


def parse_stack(raw: Any) -> HeterostructureSpec:
    """Parse and validate a JSON stack into a HeterostructureSpec (raises StackError)."""
    if not isinstance(raw, dict):
        raise StackError("stack must be an object with 'layers', 'interfaces' and 'pec_bottom'.")
    layers_raw = raw.get("layers")
    if not isinstance(layers_raw, list) or len(layers_raw) == 0:
        raise StackError("stack.layers must be a non-empty list.")
    if len(layers_raw) > MAX_LAYERS:
        raise StackError(f"stack.layers has {len(layers_raw)} layers; at most {MAX_LAYERS} are allowed.")
    pec_bottom = _strict_bool(raw, "pec_bottom", "stack", default=False)

    layers: list[LayerSpec] = []
    tops: list[Any] = []
    for i, lr in enumerate(layers_raw):
        if not isinstance(lr, dict):
            raise StackError(f"layers[{i}] must be an object.")
        mat = parse_material(lr.get("material"), f"layers[{i}].material")
        t = lr.get("thickness_nm")
        if t is not None:
            if isinstance(t, bool) or not isinstance(t, (int, float)):
                raise StackError(f"layers[{i}].thickness_nm must be a number or null.")
            t = float(t)
            if not math.isfinite(t):
                t = None  # +inf -> semi-infinite
            elif t <= 0.0:
                raise StackError(f"layers[{i}].thickness_nm must be > 0 (got {t}).")
        layers.append(LayerSpec(material=mat, thickness_nm=t))
        tops.append(lr.get("graphene_top"))

    ifaces_raw = raw.get("interfaces")
    n_if = len(layers) - 1

    # A trailing PEC layer is shorthand for pec_bottom = true.
    if layers[-1].material.kind == "pec":
        if len(layers) < 3:
            raise StackError("A PEC layer must be preceded by at least one finite spacer layer.")
        pec_top = parse_graphene(tops[-1], f"layers[{len(layers) - 1}].graphene_top")
        if isinstance(ifaces_raw, list) and len(ifaces_raw) == n_if:
            pec_top = parse_graphene(ifaces_raw[-1], f"interfaces[{n_if - 1}]")
            ifaces_raw = ifaces_raw[:-1]
        if pec_top.enabled:
            raise StackError("Graphene directly on a PEC (zero spacer) is not allowed.")
        layers = layers[:-1]
        tops = tops[:-1]
        pec_bottom = True
        n_if = len(layers) - 1
    for i, layer in enumerate(layers):
        if layer.material.kind == "pec":
            raise StackError(f"layers[{i}]: PEC is only allowed as the last layer (or via pec_bottom).")

    if ifaces_raw is None:
        interfaces = [parse_graphene(tops[i + 1], f"layers[{i + 1}].graphene_top") for i in range(n_if)]
    else:
        if not isinstance(ifaces_raw, list):
            raise StackError("stack.interfaces must be a list.")
        if len(ifaces_raw) != n_if:
            raise StackError(f"stack.interfaces must have len(layers) - 1 = {n_if} entries (got {len(ifaces_raw)}).")
        interfaces = [parse_graphene(g, f"interfaces[{i}]") for i, g in enumerate(ifaces_raw)]
    for i in range(n_if):
        layers[i + 1].graphene_top = interfaces[i]

    # Half-spaces: a thickness given for the top medium, or for the bottom medium without PEC,
    # is irrelevant (semi-infinite) and is ignored.
    if len(layers) >= 2:
        layers[0].thickness_nm = None
        if not pec_bottom:
            layers[-1].thickness_nm = None

    stack = HeterostructureSpec(layers=layers, interfaces=interfaces, pec_bottom=pec_bottom)
    try:
        validate_stack(stack)
    except ValueError as exc:
        raise StackError(str(exc)) from exc
    return stack


