def material_to_json(mat: MaterialSpec) -> dict[str, Any]:
    out: dict[str, Any] = {"id": mat.id, "name": mat.name, "kind": mat.kind}
    if mat.kind == "dielectric":
        out["eps_inf"] = mat.eps_inf
    elif mat.kind == "lorentz":
        out.update(eps_inf=mat.eps_inf, w_t=mat.w_t, w_l=mat.w_l, gamma=mat.gamma)
    elif mat.kind == "drude":
        out.update(eps_inf=mat.eps_inf, w_p=mat.w_p, gamma=mat.gamma)
    elif mat.kind == "multi_lorentz":
        out.update(
            eps_inf=mat.eps_inf,
            form=mat.multi_form,
            w_p=mat.w_p,
            gamma=mat.gamma,
            oscillators=[{k: v for k, v in asdict(o).items() if v is not None} for o in mat.oscillators],
        )
    elif mat.kind == "uniaxial_hbn":
        assert mat.parallel is not None and mat.perp is not None

        def _ax(a: UniaxialAxisParams) -> dict[str, Any]:
            d = {"eps_inf": a.eps_inf, "w_t": a.w_t, "w_l": a.w_l, "gamma": a.gamma}
            if a.oscillators:
                d["oscillators"] = [{k: v for k, v in asdict(o).items() if v is not None} for o in a.oscillators]
            return d

        out.update(eps_inf=mat.eps_inf, parallel=_ax(mat.parallel), perp=_ax(mat.perp))
    return out


def graphene_to_json(g: GrapheneSpec) -> dict[str, Any]:
    return {
        "enabled": g.enabled,
        "ef_ev": g.ef_ev,
        "tau_ps": g.tau_ps,
        "gamma_ev": g.gamma_ev,
        "model": g.model,
        "temperature_k": g.temperature_k,
        "scale": g.scale,
    }


def stack_to_json(stack: HeterostructureSpec) -> dict[str, Any]:
    layers = []
    for i, layer in enumerate(stack.layers):
        layers.append(
            {
                "material": material_to_json(layer.material),
                "thickness_nm": layer.thickness_nm,
                "graphene_top": graphene_to_json(stack.interfaces[i - 1]) if i >= 1 else None,
            }
        )
    return {
        "layers": layers,
        "interfaces": [graphene_to_json(g) for g in stack.interfaces],
        "pec_bottom": stack.pec_bottom,
    }
